class BlogManager{constructor(){this.currentPosts=[];this.filteredPosts=[];this.currentPlatform='all';this.currentCategory='all';this.currentSort='date-desc';this.postsPerPage=9;this.currentPage=1;this.searchQuery='';this.activeFilters=new Map();this.recentSearches=JSON.parse(localStorage.getItem('recentSearches')||'[]');this.searchSuggestions=[];this.currentSuggestionIndex=-1;this.initBlogFeatures();}initBlogFeatures(){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{setTimeout(()=>{this.loadBlogPosts();this.initPlatformFilters();this.initCategoryFilters();this.initSorting();this.initSearch();this.initSearchEnhancements();this.initLoadMore();this.initProgressBar();this.initMobileToggle();this.initActiveFilters();this.initKeyboardNavigation();this.initAccessibility();this.initBreadcrumbs();},100);});}else{setTimeout(()=>{this.loadBlogPosts();this.initPlatformFilters();this.initCategoryFilters();this.initSorting();this.initSearch();this.initSearchEnhancements();this.initLoadMore();this.initProgressBar();this.initMobileToggle();this.initActiveFilters();this.initKeyboardNavigation();this.initAccessibility();this.initBreadcrumbs();},100);}}loadBlogPosts(){if(typeof resourcesData==='undefined'){console.error('Blog data not loaded');setTimeout(()=>{if(typeof resourcesData!=='undefined'){this.loadBlogPosts();}else{console.error('Blog data still not available after delay');}},500);return;}this.currentPosts=resourcesData.getAllPosts();this.filteredPosts=[...this.currentPosts];this.renderPosts();this.updateResultsCount();this.updatePlatformButtons();this.updateCategoryButtons();this.updateActiveFilters();}initSorting(){const sortSelect=document.getElementById('sort-select');if(!sortSelect)return;sortSelect.addEventListener('change',(e)=>{this.currentSort=e.target.value;this.filterAndSortPosts();});}initSearch(){const searchInput=document.getElementById('search-input');const searchClear=document.getElementById('search-clear');if(searchInput){const performSearch=()=>{const query=searchInput.value.trim();this.filterAndSortPosts(query);if(searchClear){searchClear.style.display=query ? 'flex' : 'none';}};searchInput.addEventListener('input',this.constructor.debounce(performSearch,300));if(searchClear){searchClear.addEventListener('click',()=>{searchInput.value='';searchClear.style.display='none';this.filterAndSortPosts('');searchInput.focus();});}searchInput.addEventListener('keypress',(e)=>{if(e.key==='Enter'){e.preventDefault();performSearch();}});}}initPlatformFilters(){const platformFilters=document.querySelectorAll('.filter-btn[data-platform]');platformFilters.forEach(button=>{button.addEventListener('click',(e)=>{e.preventDefault();platformFilters.forEach(btn=>{btn.classList.remove('active');btn.setAttribute('aria-pressed','false');});button.classList.add('active');button.setAttribute('aria-pressed','true');const platform=button.dataset.platform;this.currentPlatform=platform;this.filterAndSortPosts();this.onFilterChange();});});}initCategoryFilters(){if(typeof resourcesData!=='undefined'&&resourcesData.getUniqueCategories){const categoryContainer=document.getElementById('category-filters');if(categoryContainer){const existingButtons=categoryContainer.querySelectorAll('.filter-btn:not([data-category="all"])');existingButtons.forEach(btn=>btn.remove());const categories=resourcesData.getUniqueCategories();categories.forEach(category=>{const button=document.createElement('button');button.className='filter-btn';button.dataset.category=category;button.textContent=category;button.setAttribute('aria-pressed','false');categoryContainer.appendChild(button);});}}const categoryFilters=document.querySelectorAll('.filter-btn[data-category]');categoryFilters.forEach(button=>{button.addEventListener('click',(e)=>{e.preventDefault();categoryFilters.forEach(btn=>{btn.classList.remove('active');btn.setAttribute('aria-pressed','false');});button.classList.add('active');button.setAttribute('aria-pressed','true');const category=button.dataset.category;this.currentCategory=category;this.filterAndSortPosts();this.onFilterChange();});});}filterAndSortPosts(searchQuery=''){this.showLoadingState();this.searchQuery=searchQuery;let posts=[...this.currentPosts];if(this.currentPlatform!=='all'){posts=posts.filter(post=>post.platform===this.currentPlatform);}if(this.currentCategory!=='all'){posts=posts.filter(post=>post.category===this.currentCategory);}if(searchQuery){posts=posts.filter(post=>post.title.toLowerCase().includes(searchQuery.toLowerCase())||post.excerpt.toLowerCase().includes(searchQuery.toLowerCase())||post.tags.some(tag=>tag.toLowerCase().includes(searchQuery.toLowerCase())));}posts.sort((a,b)=>{switch(this.currentSort){case 'date-desc': return new Date(b.date)-new Date(a.date);case 'date-asc': return new Date(a.date)-new Date(b.date);case 'reading-time-asc': return parseInt(a.readingTime)-parseInt(b.readingTime);case 'reading-time-desc': return parseInt(b.readingTime)-parseInt(a.readingTime);case 'title-asc': return a.title.localeCompare(b.title);case 'title-desc': return b.title.localeCompare(a.title);default: return 0;}});this.filteredPosts=posts;this.currentPage=1;this.renderPosts();this.updateResultsCount();setTimeout(()=>{const resourceContent=document.querySelector('.resource-content');if(resourceContent){const offsetTop=resourceContent.offsetTop-80;window.scrollTo({top: offsetTop,behavior: 'smooth'});}else{const contentMain=document.querySelector('.content-main');if(contentMain){const offsetTop=contentMain.offsetTop-80;window.scrollTo({top: offsetTop,behavior: 'smooth'});}}},100);}renderPosts(){const postsGrid=document.getElementById('posts-grid');if(!postsGrid)return;this.hideLoadingState();const postsToShow=this.filteredPosts.slice(0,this.currentPage*this.postsPerPage);if(postsToShow.length===0){this.showEmptyState();return;}else{this.hideEmptyState();}postsGrid.innerHTML=postsToShow.map(post=>{const platformIcon=resourcesData.getPlatformIcon(post.platform);const platformName=resourcesData.getPlatformName(post.platform);const actionText=post.platform==='youtube' ? 'Watch on' : 'Read on';return `<article class="post-card" data-platform="${post.platform}" data-url="${post.url}" tabindex="0" role="article"><div class="post-card-header"><div class="post-card-category">${post.tags[0]}</div><div class="post-card-date">${post.date}</div></div><div class="post-card-image"><img src="${post.image}" alt="${post.title}" loading="lazy"><div class="post-card-platform" title="${platformName}"><svg viewBox="0 0 24 24" fill="currentColor">${platformIcon}</svg></div></div><div class="post-card-content"><h3 class="post-card-title">${post.title}</h3><p class="post-card-excerpt">${post.excerpt}</p><div class="post-card-meta"><span class="post-card-reading-time">${post.readingTime}</span><div class="post-card-tags">${post.tags.map(tag=>`<span class="tag">${tag}</span>`).join('')}</div></div><a href="${post.url}" class="post-card-link btn btn-outline" target="_blank" rel="noopener noreferrer">${actionText}${platformName}</a></div></article>`;}).join('');this.addCardClickHandlers();this.updateLoadMoreButton();this.initLazyLoading();}updateLoadMoreButton(){const loadMoreBtn=document.getElementById('load-more-btn');if(!loadMoreBtn)return;const totalShowing=this.currentPage*this.postsPerPage;const hasMore=totalShowing<this.filteredPosts.length;loadMoreBtn.style.display=hasMore ? 'block' : 'none';}updateResultsCount(){const resultsCount=document.getElementById('results-count');if(!resultsCount)return;const totalShowing=Math.min(this.currentPage*this.postsPerPage,this.filteredPosts.length);const total=this.filteredPosts.length;if(total===0){resultsCount.textContent='No posts found';}else if(totalShowing===total){resultsCount.textContent=`Showing all ${total}${total===1 ? 'post' : 'posts'}`;}else{resultsCount.textContent=`Showing ${totalShowing}of ${total}${total===1 ? 'post' : 'posts'}`;}}initLoadMore(){const loadMoreBtn=document.getElementById('load-more-btn');if(!loadMoreBtn)return;loadMoreBtn.addEventListener('click',()=>{this.currentPage++;this.renderPosts();this.updateResultsCount();});}initProgressBar(){const progressBar=document.createElement('div');progressBar.className='reading-progress';progressBar.style.cssText=` position: fixed;top: 0;left: 0;width: 0%;height: 3px;background: var(--primary-color);z-index: 1000;transition: width 0.3s ease;`;document.body.appendChild(progressBar);window.addEventListener('scroll',()=>{const scrolled=window.pageYOffset;const maxHeight=document.documentElement.scrollHeight-window.innerHeight;const progress=(scrolled/maxHeight)*100;progressBar.style.width=Math.min(progress,100)+'%';});}initLazyLoading(){if('IntersectionObserver' in window){const imageObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src||img.src;img.classList.remove('lazy');imageObserver.unobserve(img);}});});document.querySelectorAll('img[loading="lazy"]').forEach(img=>{imageObserver.observe(img);});}}addCardClickHandlers(){const postCards=document.querySelectorAll('.post-card');postCards.forEach(card=>{card.addEventListener('click',(e)=>{if(e.target.closest('.post-card-link')||e.target.closest('a')){return;}const url=card.getAttribute('data-url');if(url){window.open(url,'_blank','noopener,noreferrer');}});card.style.cursor='pointer';});}initMobileToggle(){const mobileToggle=document.getElementById('mobile-filter-toggle');const sidebar=document.querySelector('.filters-sidebar');if(!mobileToggle||!sidebar)return;const overlay=document.createElement('div');overlay.className='sidebar-overlay';document.body.appendChild(overlay);mobileToggle.addEventListener('click',()=>{sidebar.classList.toggle('active');overlay.classList.toggle('active');document.body.style.overflow=sidebar.classList.contains('active')? 'hidden' : 'auto';});overlay.addEventListener('click',()=>{sidebar.classList.remove('active');overlay.classList.remove('active');document.body.style.overflow='auto';});document.addEventListener('click',(e)=>{if(window.innerWidth<=768&&!sidebar.contains(e.target)&&!mobileToggle.contains(e.target)&&sidebar.classList.contains('active')){sidebar.classList.remove('active');overlay.classList.remove('active');document.body.style.overflow='auto';}});window.addEventListener('resize',()=>{if(window.innerWidth>768){sidebar.classList.remove('active');overlay.classList.remove('active');document.body.style.overflow='auto';}});}initActiveFilters(){this.updateActiveFilters();}updateActiveFilters(){const activeFiltersSection=document.getElementById('active-filters');const activeFiltersList=document.getElementById('active-filters-list');if(!activeFiltersSection||!activeFiltersList)return;activeFiltersList.innerHTML='';const filters=[];if(this.currentPlatform!=='all'){filters.push({type: 'Platform',value: this.currentPlatform,key: 'platform'});}if(this.currentCategory!=='all'){filters.push({type: 'Category',value: this.currentCategory,key: 'category'});}if(this.searchQuery){filters.push({type: 'Search',value: this.searchQuery,key: 'search'});}if(filters.length===0){activeFiltersSection.classList.add('hidden');return;}activeFiltersSection.classList.remove('hidden');filters.forEach(filter=>{const pill=document.createElement('div');pill.className='filter-pill';pill.innerHTML=`<span>${filter.type}: ${filter.value}</span><button class="filter-pill-remove" data-filter="${filter.key}" aria-label="Remove ${filter.type}filter"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button>`;const removeBtn=pill.querySelector('.filter-pill-remove');removeBtn.addEventListener('click',(e)=>{e.stopPropagation();this.removeFilter(filter.key);});activeFiltersList.appendChild(pill);});const clearAllBtn=document.createElement('button');clearAllBtn.className='clear-all-filters';clearAllBtn.textContent='Clear All';clearAllBtn.addEventListener('click',()=>{this.clearAllFilters();});activeFiltersList.appendChild(clearAllBtn);}removeFilter(filterKey){switch(filterKey){case 'platform': this.currentPlatform='all';break;case 'category': this.currentCategory='all';break;case 'search': this.searchQuery='';document.getElementById('search-input').value='';break;}this.filterAndSortPosts(this.searchQuery);this.onFilterChange();}clearAllFilters(){this.currentPlatform='all';this.currentCategory='all';this.searchQuery='';document.getElementById('search-input').value='';this.filterAndSortPosts('');this.onFilterChange();}updatePlatformButtons(){const buttons=document.querySelectorAll('[data-platform]');buttons.forEach(btn=>{const platform=btn.getAttribute('data-platform');if(platform===this.currentPlatform){btn.classList.add('active');btn.setAttribute('aria-pressed','true');}else{btn.classList.remove('active');btn.setAttribute('aria-pressed','false');}});}updateCategoryButtons(){const buttons=document.querySelectorAll('[data-category]');buttons.forEach(btn=>{const category=btn.getAttribute('data-category');if(category===this.currentCategory){btn.classList.add('active');btn.setAttribute('aria-pressed','true');}else{btn.classList.remove('active');btn.setAttribute('aria-pressed','false');}});}initSearchEnhancements(){const searchInput=document.getElementById('search-input');const searchSuggestions=document.getElementById('search-suggestions');const suggestionsList=document.getElementById('suggestions-list');if(!searchInput||!searchSuggestions||!suggestionsList)return;this.buildSearchSuggestions();searchInput.addEventListener('focus',()=>{this.showSearchSuggestions();});searchInput.addEventListener('blur',()=>{setTimeout(()=>{this.hideSearchSuggestions();},200);});let searchTimeout;searchInput.addEventListener('input',(e)=>{clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{this.handleSearchInput(e.target.value);},300);});searchInput.addEventListener('keydown',(e)=>{this.handleSearchKeyboard(e);});}buildSearchSuggestions(){const suggestions=new Set();this.currentPosts.forEach(post=>{post.title.split(' ').forEach(word=>{if(word.length>2){suggestions.add(word.toLowerCase());}});suggestions.add(post.category.toLowerCase());suggestions.add(post.platform.toLowerCase());post.tags.forEach(tag=>{suggestions.add(tag.toLowerCase());});});this.searchSuggestions=Array.from(suggestions).sort();}showSearchSuggestions(){const searchSuggestions=document.getElementById('search-suggestions');if(searchSuggestions){searchSuggestions.classList.add('active');this.populateRecentSearches();}}hideSearchSuggestions(){const searchSuggestions=document.getElementById('search-suggestions');if(searchSuggestions){searchSuggestions.classList.remove('active');}}handleSearchInput(query){if(query.length<2){this.populateRecentSearches();return;}const filteredSuggestions=this.searchSuggestions.filter(suggestion=>suggestion.includes(query.toLowerCase())).slice(0,5);this.populateSuggestions(filteredSuggestions,query);}populateRecentSearches(){const recentSearchesContainer=document.getElementById('recent-searches');const suggestionsList=document.getElementById('suggestions-list');if(!recentSearchesContainer||!suggestionsList)return;suggestionsList.innerHTML='';if(this.recentSearches.length===0){recentSearchesContainer.style.display='none';return;}recentSearchesContainer.style.display='block';const recentList=recentSearchesContainer.querySelector('.recent-searches-list')||document.createElement('div');recentList.className='recent-searches-list';recentList.innerHTML='';this.recentSearches.slice(0,3).forEach(search=>{const item=document.createElement('div');item.className='recent-search-item';item.innerHTML=`<svg class="recent-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><polyline points="12,6 12,12 16,14"></polyline></svg><span>${search}</span>`;item.addEventListener('click',()=>{this.selectSuggestion(search);});recentList.appendChild(item);});recentSearchesContainer.appendChild(recentList);}populateSuggestions(suggestions,query){const suggestionsList=document.getElementById('suggestions-list');if(!suggestionsList)return;suggestionsList.innerHTML='';if(suggestions.length===0){suggestionsList.innerHTML='<div class="search-no-results">No suggestions found</div>';return;}suggestions.forEach((suggestion,index)=>{const item=document.createElement('div');item.className='search-suggestion';item.setAttribute('data-suggestion',suggestion);item.innerHTML=`<svg class="search-suggestion-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><path d="M21 21l-4.35-4.35"></path></svg><span class="search-suggestion-text">${this.highlightMatch(suggestion,query)}</span><span class="search-suggestion-type">Search</span>`;item.addEventListener('click',()=>{this.selectSuggestion(suggestion);});suggestionsList.appendChild(item);});}highlightMatch(text,query){const regex=new RegExp(`(${query})`,'gi');return text.replace(regex,'<strong>$1</strong>');}selectSuggestion(suggestion){const searchInput=document.getElementById('search-input');if(searchInput){searchInput.value=suggestion;this.searchQuery=suggestion;this.saveRecentSearch(suggestion);this.hideSearchSuggestions();this.filterAndSortPosts(suggestion);this.updateActiveFilters();}}saveRecentSearch(query){this.recentSearches=this.recentSearches.filter(search=>search!==query);this.recentSearches.unshift(query);this.recentSearches=this.recentSearches.slice(0,5);localStorage.setItem('recentSearches',JSON.stringify(this.recentSearches));}handleSearchKeyboard(e){const suggestions=document.querySelectorAll('.search-suggestion,.recent-search-item');if(e.key==='ArrowDown'){e.preventDefault();this.currentSuggestionIndex=Math.min(this.currentSuggestionIndex+1,suggestions.length-1);this.highlightSuggestion(suggestions);}else if(e.key==='ArrowUp'){e.preventDefault();this.currentSuggestionIndex=Math.max(this.currentSuggestionIndex-1,-1);this.highlightSuggestion(suggestions);}else if(e.key==='Enter'){e.preventDefault();if(this.currentSuggestionIndex>=0&&suggestions[this.currentSuggestionIndex]){const suggestion=suggestions[this.currentSuggestionIndex];const text=suggestion.querySelector('.search-suggestion-text,span')?.textContent;if(text){this.selectSuggestion(text);}}}else if(e.key==='Escape'){this.hideSearchSuggestions();}}highlightSuggestion(suggestions){suggestions.forEach((suggestion,index)=>{suggestion.classList.toggle('keyboard-focus',index===this.currentSuggestionIndex);});}showLoadingState(){const postsGrid=document.getElementById('posts-grid');const skeletonContainer=document.getElementById('skeleton-container');if(postsGrid&&skeletonContainer){postsGrid.classList.add('loading');skeletonContainer.classList.remove('hidden');}}hideLoadingState(){const postsGrid=document.getElementById('posts-grid');const skeletonContainer=document.getElementById('skeleton-container');if(postsGrid&&skeletonContainer){postsGrid.classList.remove('loading');skeletonContainer.classList.add('hidden');}}showEmptyState(){const emptyState=document.getElementById('empty-state');const postsGrid=document.getElementById('posts-grid');if(emptyState&&postsGrid){emptyState.classList.remove('hidden');postsGrid.style.display='none';}}hideEmptyState(){const emptyState=document.getElementById('empty-state');const postsGrid=document.getElementById('posts-grid');if(emptyState&&postsGrid){emptyState.classList.add('hidden');postsGrid.style.display='grid';}}initKeyboardNavigation(){document.addEventListener('keydown',(e)=>{if(e.key==='Tab'){document.body.classList.add('keyboard-navigation');}});document.addEventListener('mousedown',()=>{document.body.classList.remove('keyboard-navigation');});const postCards=document.querySelectorAll('.post-card');postCards.forEach(card=>{card.setAttribute('tabindex','0');card.addEventListener('keydown',(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const link=card.querySelector('.post-card-link');if(link){link.click();}}});});}initAccessibility(){this.updateAriaLabels();const resultsCount=document.getElementById('results-count');if(resultsCount){resultsCount.setAttribute('aria-live','polite');resultsCount.setAttribute('aria-atomic','true');}this.initFilterButtonStates();}initFilterButtonStates(){const allButtons=document.querySelectorAll('.filter-btn');allButtons.forEach(btn=>{if(!btn.hasAttribute('aria-pressed')){btn.setAttribute('aria-pressed','false');}});const allPlatformBtn=document.querySelector('[data-platform="all"]');if(allPlatformBtn){allPlatformBtn.setAttribute('aria-pressed','true');}const allCategoryBtn=document.querySelector('[data-category="all"]');if(allCategoryBtn){allCategoryBtn.setAttribute('aria-pressed','true');}}updateAriaLabels(){const filterButtons=document.querySelectorAll('.filter-btn');filterButtons.forEach(btn=>{const isActive=btn.classList.contains('active');btn.setAttribute('aria-pressed',isActive);btn.setAttribute('role','button');});}onFilterChange(){this.updatePlatformButtons();this.updateCategoryButtons();this.updateActiveFilters();this.updateAriaLabels();}static debounce(func,wait){return Utils ? Utils.debounce(func,wait): this.fallbackDebounce(func,wait);}static fallbackDebounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout=setTimeout(later,wait);};}initBreadcrumbs(){if(typeof window.ResilioCommon!=='undefined'){const common=new window.ResilioCommon();common.initBreadcrumbs();}}}document.addEventListener('DOMContentLoaded',()=>{new BlogManager();});